class Solution {
public:
    string complexNumberMultiply(string num1, string num2) {
        int a, b, c, d;
        char plus, i_char;
        stringstream ss1(num1), ss2(num2);
        ss1 >> a >> plus >> b >> i_char;
        ss2 >> c >> plus >> d >> i_char;
        int real = a * c - b * d;
        int imag = a * d + b * c;
        return to_string(real) + "+" + to_string(imag) + "i";
    }
};

class Solution {
    public String complexNumberMultiply(String num1, String num2) {
        String[] p1 = num1.substring(0, num1.length() - 1).split("\\+");
        String[] p2 = num2.substring(0, num2.length() - 1).split("\\+");
        int a = Integer.parseInt(p1[0]), b = Integer.parseInt(p1[1]);
        int c = Integer.parseInt(p2[0]), d = Integer.parseInt(p2[1]);
        int real = a * c - b * d;
        int imag = a * d + b * c;
        return real + "+" + imag + "i";
    }
}

var complexNumberMultiply = function(num1, num2) {
    const [a, b] = num1.slice(0, -1).split('+').map(Number);
    const [c, d] = num2.slice(0, -1).split('+').map(Number);
    const real = a * c - b * d;
    const imag = a * d + b * c;
    return `${real}+${imag}i`;
};
